fn longest_prefix(a: &[i32], b: &[i32]) -> usize {
    let mut len = 0;
    let max = std::cmp::min(a.len(), b.len());
    while len < max {
        if a[len] != b[len] {
            break;
        }
        len += 1;
    }
    len
}

